#include <stdio.h>
#include <math.h>

/* Perspective ray tracer: sphere, checkerboard, and directional lighting. */
typedef struct{float x,y,z;} V;
V add(V a,V b){return(V){a.x+b.x,a.y+b.y,a.z+b.z};}
V mul(V a,double s){return(V){a.x*s,a.y*s,a.z*s};}
double dot(V a,V b){return a.x*b.x+a.y*b.y+a.z*b.z;}
double hit(V o,V d){V q=add(o,(V){0,-1,5});double a=dot(d,d),b=dot(q,d),c=dot(q,q)-1,h=b*b-a*c;if(h<0)return 1e30;double t=(-b-sqrt(h))/a;return t>1e-5?t:1e30;}
int main(){FILE*f=fopen("reconstructed.ppm","wb");if(!f)return 1;fprintf(f,"P6\n2400 1800\n255\n");V o={0,1.5,0},l={1/sqrt(3),1/sqrt(3),-1/sqrt(3)};
for(int y=0;y<1800;y++)for(int x=0;x<2400;x++){V d={(2.f*x/2399-1)*(2400.f/1800),(1-2.f*y/1799),-1};d=mul(d,1/sqrt(dot(d,d)));
double t=hit(o,d),p=d.y<0?-1.5/d.y:1e30;double r,g,b;if(t< p){V n=add(add(o,mul(d,t)),(V){0,-1,5});double s=.2+.8*fmax(0,dot(n,l));r=s;g=b=.2*s;}
else if(p<1e29){V q=add(o,mul(d,p));double c=((int)floor(q.x)+(int)floor(q.z))%2?.4:.9;double s=hit(add(q,(V){0,.001,0}),l)<1e29?.2:.2+.8*l.y;r=g=b=c*s;}
else{double a=.5*(d.y/sqrt(dot(d,d))+1);r=1-.5*a;g=1-.3*a;b=1;}
unsigned char rgb[3]={(int)(255.99f*r),(int)(255.99f*g),(int)(255.99f*b)};fwrite(rgb,1,3,f);}return fclose(f)!=0;}
